// Check 1: Validate successful response and data type
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});
pm.test("RPM falloff is calculated as a number", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.rpmFalloff[0]).to.be.a("number");
});

// Check 2: Validate boundary error for zero division
pm.test("Fails on zero ratio input", function () {
    // Assuming the test sent a 0.0 ratio in the pre-request script
    pm.response.to.have.status(400);
    pm.expect(pm.response.text()).to.include("Ratio cannot be zero");
});

// Check 3: Validate API contract response time
pm.test("Response time is less than 200ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(200);
});

// Check 4: Validate Content-Type is strictly JSON
pm.test("Content-Type is application/json", function () {
    pm.response.to.have.header("Content-Type", "application/json; charset=utf-8");
});
